import torch
import torch.nn as nn
from .util import init

"""
Modify standard PyTorch distributions so they to make compatible with this codebase. 
"""

#
# Standardize distribution interfaces
#

# Categorical
class FixedCategorical(torch.distributions.Categorical):
    def sample(self):
        return super().sample().unsqueeze(-1)

    def log_probs(self, actions):
        return (
            super()
            .log_prob(actions.squeeze(-1))
            .view(actions.size(0), -1)
            .sum(-1)
            .unsqueeze(-1)
        )

    def mode(self):
        return self.probs.argmax(dim=-1, keepdim=True)


# Normal
class FixedNormal(torch.distributions.Normal):
    def log_probs(self, actions):
        return super().log_prob(actions).sum(-1, keepdim=True)

    def entropy(self):
        return torch.distributions.Normal.entropy(self).sum(-1)

    def mode(self):
        return self.mean


class FixedTanhNormal(torch.distributions.Normal):
    """Normal distribution transformed to the symmetric action range [-1, 1].

    The upstream implementation uses an unconstrained Gaussian and relies on
    environments to clip actions.  That changes the action after its log
    probability has been recorded, which breaks PPO's importance ratio.  This
    wrapper keeps sampling, execution and log-prob evaluation consistent.
    """

    _eps = 1e-6

    def sample(self):
        return torch.tanh(super().sample())

    def rsample(self):
        return torch.tanh(super().rsample())

    def log_probs(self, actions):
        actions = actions.clamp(-1. + self._eps, 1. - self._eps)
        raw_actions = torch.atanh(actions)
        correction = torch.log(1. - actions.square() + self._eps)
        return (super().log_prob(raw_actions) - correction).sum(-1, keepdim=True)

    def entropy(self):
        # There is no closed-form entropy for a tanh-transformed Normal.
        # The pre-transform entropy is the stable approximation used for the
        # exploration bonus; PPO's exact ratio still uses log_probs above.
        return torch.distributions.Normal.entropy(self).sum(-1)

    def mode(self):
        return torch.tanh(self.mean)


# Bernoulli
class FixedBernoulli(torch.distributions.Bernoulli):
    def log_probs(self, actions):
        return super.log_prob(actions).view(actions.size(0), -1).sum(-1).unsqueeze(-1)

    def entropy(self):
        return super().entropy().sum(-1)

    def mode(self):
        return torch.gt(self.probs, 0.5).float()


class Categorical(nn.Module):
    def __init__(self, num_inputs, num_outputs, use_orthogonal=True, gain=0.01):
        super(Categorical, self).__init__()
        init_method = [nn.init.xavier_uniform_, nn.init.orthogonal_][use_orthogonal]
        def init_(m): 
            return init(m, init_method, lambda x: nn.init.constant_(x, 0), gain)

        self.linear = init_(nn.Linear(num_inputs, num_outputs))

    def forward(self, x, available_actions=None):
        x = self.linear(x)
        if available_actions is not None:
            x[available_actions == 0] = -1e10
        return FixedCategorical(logits=x)


class DiagGaussian(nn.Module):
    def __init__(self, num_inputs, num_outputs, use_orthogonal=True, gain=0.01,
                 tanh_actions=False, initial_logstd=0.):
        super(DiagGaussian, self).__init__()

        self.tanh_actions = tanh_actions

        init_method = [nn.init.xavier_uniform_, nn.init.orthogonal_][use_orthogonal]
        def init_(m): 
            return init(m, init_method, lambda x: nn.init.constant_(x, 0), gain)

        self.fc_mean = init_(nn.Linear(num_inputs, num_outputs))
        self.logstd = AddBias(torch.full((num_outputs,), initial_logstd))

    def forward(self, x):
        action_mean = self.fc_mean(x)

        #  An ugly hack for my KFAC implementation.
        zeros = torch.zeros(action_mean.size())
        if x.is_cuda:
            zeros = zeros.cuda()

        action_logstd = self.logstd(zeros)
        distribution = FixedTanhNormal if self.tanh_actions else FixedNormal
        return distribution(action_mean, action_logstd.exp())


class Bernoulli(nn.Module):
    def __init__(self, num_inputs, num_outputs, use_orthogonal=True, gain=0.01):
        super(Bernoulli, self).__init__()
        init_method = [nn.init.xavier_uniform_, nn.init.orthogonal_][use_orthogonal]
        def init_(m): 
            return init(m, init_method, lambda x: nn.init.constant_(x, 0), gain)
        
        self.linear = init_(nn.Linear(num_inputs, num_outputs))

    def forward(self, x):
        x = self.linear(x)
        return FixedBernoulli(logits=x)

class AddBias(nn.Module):
    def __init__(self, bias):
        super(AddBias, self).__init__()
        self._bias = nn.Parameter(bias.unsqueeze(1))

    def forward(self, x):
        if x.dim() == 2:
            bias = self._bias.t().view(1, -1)
        else:
            bias = self._bias.t().view(1, -1, 1, 1)

        return x + bias
